  FROM (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(subq_6.metric_time__month, cm_6_cte.metric_time__month) AS metric_time__month
      , MAX(subq_6.calls_with_objection) AS calls_with_objection
      , MAX(cm_6_cte.calls_labelled) AS calls_labelled
    FROM (
      -- Constrain Output with WHERE
      -- Select: ['__calls_with_objection', 'metric_time__month']
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__month
        , SUM(calls_with_objection) AS calls_with_objection
      FROM (
        -- Read From CTE For node_id=sma_10005
        -- Select: ['__calls_with_objection', 'call__objection', 'metric_time__month']
        SELECT
          metric_time__month
          , call__objection
          , __calls_with_objection AS calls_with_objection
        FROM sma_10005_cte
      ) subq_2
      WHERE call__objection <> 'none'
      GROUP BY
        metric_time__month
    ) subq_6
    FULL OUTER JOIN
      cm_6_cte
    ON
      subq_6.metric_time__month = cm_6_cte.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_12
  FULL OUTER JOIN (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(subq_19.metric_time__month, cm_6_cte.metric_time__month) AS metric_time__month
      , MAX(subq_19.positive_calls) AS positive_calls
      , MAX(cm_6_cte.calls_labelled) AS calls_labelled
    FROM (
      -- Constrain Output with WHERE
      -- Select: ['__positive_calls', 'metric_time__month']
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__month
        , SUM(positive_calls) AS positive_calls
      FROM (
        -- Read From CTE For node_id=sma_10005
        -- Select: ['__positive_calls', 'call__sentiment', 'metric_time__month']
        SELECT
          metric_time__month
          , call__sentiment
          , __positive_calls AS positive_calls
        FROM sma_10005_cte
      ) subq_15
      WHERE call__sentiment = 'positive'
      GROUP BY
        metric_time__month
    ) subq_19
    FULL OUTER JOIN
      cm_6_cte
    ON
      subq_19.metric_time__month = cm_6_cte.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_21
  ON
    subq_12.metric_time__month = subq_21.metric_time__month
  GROUP BY
    metric_time__month
) as metricflow
